const names={inicio:'Painel',producao:'Produção',catalogo:'Estoque',pedidos:'Pedidos e vendas',pdv:'PDV',caixa:'Caixas',consignacoes:'Consignações',financeiro:'Financeiro',relatorios:'Relatórios',metas:'Metas',fiscal:'Notas fiscais',cadastros:'Cadastros',usuarios:'Usuários',cheques:'Cheques',ponto:'Ponto',loja:'E-commerce',quiosque:'Autoatendimento',config:'Configurações',lojas:'Lojas'};
const paths={inicio:'M3 10 12 3l9 7v10H4V10m5 10v-7h6v7',producao:'M3 21V8l6 4V8l6 4V3h6v18H3m4-4h1m4 0h1m4 0h1',catalogo:'m12 3 9 5v9l-9 5-9-5V8l9-5m0 10v9M3 8l9 5 9-5',pedidos:'M6 3h12v18H6zM9 7h6M9 11h6m-6 4h4',pdv:'M3 10h18l-2-6H5l-2 6m1 0v11h16V10M9 21v-7h6v7',caixa:'M4 7h16v14H4zM7 7V3h10v4M4 11h16m-6 5h3',consignacoes:'m3 9 4-5 5 2 5-2 4 5-2 9-7 3-7-3-2-9m4-2 6 5 3-3m-8 8 3 2m0-6 5 5',financeiro:'M3 5h18v15H3zM3 9h18m-5 6h2M7 15h1',relatorios:'M4 3v18h17M8 16v-4m5 4V7m5 9v-6',metas:'M12 3a9 9 0 1 0 9 9m-9-5a5 5 0 1 0 5 5m-5 0 9-9m-5 0h5v5',fiscal:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6m-6 4h6',cadastros:'M4 4h16v16H4zM8 8h8m-8 4h8m-8 4h4',usuarios:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m11-14a4 4 0 1 1-8 0 4 4 0 0 1 8 0m4 8a4 4 0 0 1 5 4v2',cheques:'M3 5h18v14H3zM6 9h5m-5 4h9m-2 9 7-7',ponto:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-9-6v6l4 2',loja:'M4 7h16l-1 14H5L4 7m4 0V5a4 4 0 0 1 8 0v2',quiosque:'M5 3h14v15H5zM9 21h6m-3-3v3M9 7h6m-6 4h6',config:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',reset:'M3 10a9 9 0 1 1 1 8M3 4v6h6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',print:'M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6z',arrow:'M4 12h16m-6-6 6 6-6 6',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0'};
