const button=(label,action,id='',cls='',ico='')=>`<button class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${ico?icon(ico):''}${label}</button>`;
const badge=(text,c='')=>`<span class="badge ${c}">${esc(text)}</span>`;
const stat=(label,value,meta='',link='',color='')=>(link&&!F.allow(S,link)?'':`<${link?'a href="#'+link+'"':'div'} class="stat"><div class="stat-label">${label}</div><div class="stat-value ${color}">${value}</div><div class="stat-meta">${meta}</div></${link?'a':'div'}>`);
