const input=(label,name,value='',type='text',attrs='')=>`<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,options,value,attrs='')=>`<label class="field"><span>${label}</span><select name="${name}" ${attrs}>${opts(options,value)}</select></label>`;
const textArea=(label,name,value='')=>`<label class="field wide"><span>${label}</span><textarea name="${name}">${esc(value)}</textarea></label>`;
const scoped=arr=>arr.filter(x=>x.unit===S.unit), product=id=>S.products.find(x=>x.id===id), unitName=id=>S.units.find(x=>x.id===id)?.name||id, locName=id=>S.locations.find(x=>x.id===id)?.name||id, moneyCell=n=>`<span class="money">${brl(n)}</span>`;
const prodOptions=(kind='acabado')=>S.products.filter(p=>p.active&&p.kind===kind).map(p=>[p.id,`${p.name} · ${p.color} / ${p.size}`]);
const unitLocs=(type='')=>S.locations.filter(x=>x.unit===S.unit&&(!type||x.type===type)).map(x=>[x.id,x.name]);
const table=(heads,rows,foot='')=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${heads.length}">${empty()}</td></tr>`}</tbody></table>${foot?`<div class="table-footer">${foot}</div>`:''}</div>`;
const tabs=(items,active)=>`<div class="tabs" role="tablist">${items.map(([v,l])=>`<button class="tab ${v===active?'active':''}" role="tab" aria-selected="${v===active}" data-action="tab" data-id="${v}">${l}</button>`).join('')}</div>`;
const notice=t=>`<div class="notice">${t}</div>`;
function save(){window.CarolaDomain.migrate(S);try{localStorage.setItem(KEY,JSON.stringify(S))}catch{toast('O navegador não conseguiu salvar os dados. Exporte uma cópia em Configurações.',true)}}
function toast(text,error=false){const e=D.createElement('div');e.className='toast'+(error?' error':'');e.textContent=text;$('#toasts').append(e);setTimeout(()=>e.remove(),6500)}
function transaction(fn,msg){F.atomic(S,fn);save();close();render();if(msg)toast(msg)}
function modal(title,body,form='',submitLabel='Salvar'){lastFocus=D.activeElement;$('#dialog-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="dialog-body">${form?`<form data-form="${form}">`:''}${body}${form?`<p class="form-error" role="alert"></p><div class="dialog-footer">${button('Cancelar','close')}<button class="btn primary" type="submit">${submitLabel}</button></div></form>`:''}</div>`;$('#dialog').showModal();$('#dialog').querySelector('input,select,textarea,button')?.focus()}
function close(){if($('#dialog').open){$('#dialog').close();lastFocus?.focus?.()}}
function header(desc='',actions=''){return `<header class="page-head"><div><div class="row"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><h1>${names[route]}</h1><span class="demo-tag">Demonstração</span></div><p>${desc||`${esc(F.user(S).name)} · ${unitName(S.unit)}`}</p></div><div class="head-actions">${actions}</div></header>`}
function sidebar(){const groups=[['Visão geral',['inicio','producao','catalogo']],['Operação',['pedidos','caixa','consignacoes','financeiro','relatorios','metas']],['Fiscal',['fiscal']],['Cadastros',['cadastros','usuarios','lojas']],['Canais e recursos',['quiosque','cheques','ponto']],['Sistema',['config']]];$('#sidebar').innerHTML=`<div class="brand"><div class="space"><a href="#inicio" class="brand-copy"><b>Fluxo Moda</b><p>Comércio unificado para moda</p></a><button class="icon-btn" data-action="collapse" aria-label="Recolher ou expandir menu">${icon('menu')}</button></div></div><nav>${groups.map(([name,list])=>{list=list.filter(k=>F.allow(S,k));return list.length?`<div class="group"><div class="nav-label">${name}</div>${list.map(k=>`<a href="#${k}" class="${route===k?'active':''}" title="${names[k]}" ${route===k?'aria-current="page"':''}>${icon(k)}<span class="nav-text">${names[k]}</span></a>`).join('')}</div>`:''}).join('')}</nav><div class="session"><label for="demo-user">Usuário simulado</label><select id="demo-user" data-setting="user">${opts(S.users.filter(x=>x.active).map(x=>[x.id,x.name]),S.user)}</select><label for="demo-unit">Unidade</label><select id="demo-unit" data-setting="unit">${opts(S.units.filter(x=>F.user(S).units.includes(x.id)).map(x=>[x.id,x.name]),S.unit)}</select><p class="note muted">Dados fictícios · salvos neste navegador</p><button class="reset" data-action="reset">${icon('reset')} Reiniciar demonstração</button></div>`}
const netOrder=o=>Math.max(0,F.round(o.total-S.returns.filter(r=>r.orderId===o.id).reduce((a,r)=>a+r.amount,0)));
const saleOrders=()=>scoped(S.orders).filter(o=>o.status!=='Orçamento');
function lineChart(values,labels){let max=Math.max(...values,0),min=Math.min(...values,0);if(max===min)max=min+1;const range=max-min,w=600,top=12,bottom=172,pad=44,y=v=>top+(max-v)/range*(bottom-top),zero=y(0),points=values.map((v,i)=>[pad+i*(w-pad-12)/Math.max(values.length-1,1),y(v)]);return `<svg class="chart" viewBox="0 0 600 205" role="img" aria-label="Vendas líquidas no período, incluindo devoluções">${[0,.25,.5,.75,1].map(t=>{const v=min+range*t;return `<line x1="44" y1="${y(v)}" x2="590" y2="${y(v)}" stroke="#e1e4da" stroke-dasharray="3 4"/><text x="0" y="${y(v)+4}">${num(v/1000)}k</text>`}).join('')}<line x1="44" y1="${zero}" x2="590" y2="${zero}" stroke="#b9c6b2"/><path d="M${pad},${zero} L${points.map(p=>p.join(',')).join(' L')} L${points.at(-1)[0]},${zero}Z" fill="#61836926"/><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#618369" stroke-width="2"/>${points.map((p,i)=>i%Math.max(1,Math.floor(values.length/7))===0?`<text x="${p[0]}" y="198" text-anchor="${i===values.length-1?'end':i===0?'start':'middle'}">${labels[i]}</text>`:'').join('')}</svg>`}
function dashboard(){const sales=saleOrders(),month=sales.filter(o=>o.date>=F.month),daily=sales.filter(o=>o.date===F.today),ops=scoped(S.ops).filter(o=>!o.stockPosted),titles=scoped(S.titles),low=S.products.filter(p=>p.active&&p.kind==='acabado'&&F.at(S,p.id,S.unit)<=p.min),late=ops.filter(o=>o.due<F.today),days=Number(filter.days||7),dailyTotals=Array.from({length:days},(_,i)=>{let date=F.offset(i-days+1);return {date,value:sales.filter(o=>o.date===date).reduce((a,o)=>a+netOrder(o),0)}}),monthTotal=month.reduce((a,o)=>a+netOrder(o),0),paid=titles.filter(t=>t.status==='Pago'&&t.paid===F.today),ins=paid.filter(t=>t.type==='receber').reduce((a,t)=>a+t.amount,0),outs=paid.filter(t=>t.type==='pagar').reduce((a,t)=>a+t.amount,0);
 let ranking={};month.forEach(o=>o.items.forEach(i=>ranking[i.product]=(ranking[i.product]||0)+i.qty-(i.returned||0)));const ranks=Object.entries(ranking).sort((a,b)=>b[1]-a[1]).slice(0,5);let channels=['Loja física','Representante','E-commerce','Autoatendimento'].map(c=>({name:c,value:month.filter(o=>o.channel===c).reduce((a,o)=>a+netOrder(o),0)}));
 return header('',`<label class="small muted">Período do gráfico <select data-filter="days">${opts([[7,'Últimos 7 dias'],[14,'Últimos 14 dias'],[30,'Últimos 30 dias']],days)}</select></label>`)+`<div class="stats">${stat('Vendas hoje',brl(daily.reduce((a,o)=>a+netOrder(o),0)),daily.length+' vendas','pedidos')}${stat('Vendas no mês',brl(monthTotal),month.length+' vendas','relatorios')}${stat('Ticket médio',brl(monthTotal/(month.length||1)),'Vendas líquidas ÷ vendas do mês','relatorios')}${stat('Ordens em produção',ops.length,late.length+' atrasada(s)','producao',late.length?'red':'')}${stat('Estoque baixo',low.length,'Limite definido por produto','catalogo',low.length?'amber':'')}${stat('Caixas abertos',scoped(S.cash).filter(c=>c.open).length,'Na unidade atual','caixa')}${stat('Contas a receber',brl(titles.filter(t=>t.type==='receber'&&t.status==='Aberto').reduce((a,t)=>a+t.amount,0)),'Saldo em aberto','financeiro')}${stat('Contas a pagar',brl(titles.filter(t=>t.type==='pagar'&&t.status==='Aberto').reduce((a,t)=>a+t.amount,0)),'Saldo em aberto','financeiro')}${stat('Entradas do dia',brl(ins),'Recebimentos confirmados','financeiro')}${stat('Saídas do dia',brl(outs),'Pagamentos confirmados','financeiro')}${stat('Saldo do dia',brl(ins-outs),'Entradas menos saídas','financeiro')}${stat('Clientes ativos',new Set(sales.filter(o=>o.date>=F.offset(-2)).map(o=>o.client)).size,'Com vendas nos últimos 3 dias','pedidos')}</div><div class="chart-grid"><section class="card"><h2>Vendas dos últimos ${days} dias</h2>${lineChart(dailyTotals.map(x=>x.value),dailyTotals.map(x=>dt(x.date).slice(0,5)))}</section><section class="card"><h2>Canais no mês</h2><div class="bars">${channels.map((c,i)=>`<div class="bar-col"><b>${brl(c.value)}</b><i style="height:${Math.max(2,c.value/Math.max(...channels.map(x=>x.value),1)*150)}px;background:${['#618369','#55839c','#ad956e','#85967e'][i]}"></i><span>${c.name==='Autoatendimento'?'Autoatend.':c.name}</span></div>`).join('')}</div></section></div><div class="grid2"><section class="card"><h2>Alertas</h2>${(F.allow(S,'producao')?late:[]).map(o=>`<a class="alert-row" href="#producao">${o.id} está atrasada ${badge('produção','red')}</a>`).join('')}${low.length&&F.allow(S,'catalogo')?`<a class="alert-row" href="#catalogo">${low.length} variantes com estoque baixo ${badge('estoque','amber')}</a>`:''}${F.allow(S,'financeiro')&&titles.filter(t=>t.status==='Aberto'&&t.due<F.today).length?`<a class="alert-row" href="#financeiro">Há contas vencidas ${badge('financeiro','amber')}</a>`:''}${!late.length&&!low.length&&!titles.some(t=>t.status==='Aberto'&&t.due<F.today)?empty('Nenhum alerta nesta unidade.'):''}<h2 class="mt">Produtos mais vendidos</h2>${ranks.map(([p,n],i)=>`<div class="alert-row"><span>${i+1}. ${esc(product(p).name)}</span><b>${n} peças</b></div>`).join('')||empty('Sem vendas no período.')}</section><section class="card"><h2>Atividades recentes</h2>${S.activity.filter(a=>!a.unit||a.unit===S.unit).slice(0,7).map(a=>`<div class="activity">${esc(a.text)}<small>${dt(a.date)} · ${a.time||'—'}</small></div>`).join('')}<div class="notice green mt">${esc(S.settings.company)} · ${esc(S.settings.collection)}</div></section></div>`}
function production(){const current=tab.producao||'kanban';const orders=scoped(S.ops);const opCard=o=>`<article class="card"><div class="space"><span class="op-name">${esc(product(o.product).name)}</span>${o.due<F.today&&!o.stockPosted?badge('atrasada','red'):''}</div><div class="op-id">${o.id} · lote ${esc(o.lot)}</div><div class="progress"><i style="width:${o.stage/7*100}%"></i></div><div class="op-meta"><span>Previsto: ${o.planned}</span><span>Real: ${o.actual}</span><span>Defeitos: ${o.defects}</span><span>Prazo: ${dt(o.due)}</span></div><p class="small muted mb">Resp.: ${esc(o.worker)}</p><div class="row">${button(o.stockPosted?'Ver ordem':'Gerenciar','op',o.id,'sm')}${button('Rastreabilidade','trace',o.id,'sm plain')}</div></article>`;
return header('Coleções, fichas técnicas e ordens de produção.',button('Novo modelo','product-new','','','plus')+button('Nova ordem','op-new','','primary','plus'))+tabs([['kanban','Kanban'],['lista','Lista'],['modelos','Modelos']],current)+(current==='modelos'?catalogCards(S.products.filter(p=>p.kind==='acabado'&&p.active)):current==='lista'?table(['Ordem / lote','Produto','Etapa','Previsão','Quantidade',''],orders.map(o=>`<tr><td><b>${o.id}</b><small>${esc(o.lot)}</small></td><td>${esc(product(o.product).name)}</td><td>${badge(F.stages[o.stage],o.stockPosted?'green':'blue')}</td><td>${dt(o.due)}</td><td>${o.actual} / ${o.planned}</td><td>${button('Gerenciar','op',o.id,'sm')}</td></tr>`)):`<div class="kanban">${F.stages.map((stage,i)=>`<section class="lane"><h2 class="lane-title">${stage} (${orders.filter(o=>o.stage===i).length})</h2>${orders.filter(o=>o.stage===i).map(opCard).join('')||empty('vazio')}</section>`).join('')}</div>`)}
function catalogCards(products){return `<div class="product-grid">${products.map(p=>{const locs=S.locations.filter(l=>l.unit===S.unit&&(p.kind==='materia'?l.type==='materia':l.type!=='materia'));const n=locs.reduce((a,l)=>a+F.at(S,p.id,l.id),0);return `<article class="card product-card"><div class="space"><div><p class="product-name">${esc(p.name)}</p><p class="sub">${esc(p.ref)} · ${esc(p.category)} · ${esc(p.collection)}</p></div>${badge(p.kind==='materia'?'matéria-prima':p.published?'publicado':'não publicado',p.published?'green':'')}</div><dl class="metrics"><div><dt>Preço</dt><dd>${brl(p.price)}</dd></div><div><dt>Custo</dt><dd>${brl(p.cost)}</dd></div><div><dt>Cor / tamanho</dt><dd>${esc(p.color)} / ${esc(p.size)}</dd></div><div><dt>Estoque na unidade</dt><dd>${num(n)} ${esc(p.um)}</dd></div></dl><div class="tag-list mb">${locs.map(l=>badge(locName(l.id)+': '+num(F.at(S,p.id,l.id)),F.at(S,p.id,l.id)<=p.min?'amber':'')).join('')}</div><div class="row">${button('Editar','product',p.id,'sm')}${button('Movimentar','move',p.id,'sm')}${p.kind==='acabado'?button(p.published?'Despublicar':'Publicar','publish-product',p.id,'sm plain'):''}${button('Etiqueta','label',p.id,'sm plain','print')}${button('Duplicar variante','duplicate-product',p.id,'sm plain')}</div></article>`}).join('')||empty()}</div>`}
function catalog(){const t=tab.catalogo||'produtos',q=(filter.catalogq||'').toLowerCase();let ps=S.products.filter(p=>p.active&&(t==='materia'?p.kind==='materia':p.kind==='acabado')&&(!q||[p.name,p.ref,p.barcode].join(' ').toLowerCase().includes(q)));if(t==='baixo')ps=ps.filter(p=>F.at(S,p.id,S.unit)<=p.min);return header('Produtos, matéria-prima e movimentações por armazenador.',button('Transferir','transfer','','','arrow')+button('Novo produto','product-new','','primary','plus'))+tabs([['produtos','Produtos'],['materia','Matéria-prima'],['baixo','Estoque baixo'],['movimentos','Movimentações'],['etiquetas','Etiquetas']],t)+(t==='movimentos'?table(['Data','Produto','Armazenador','Quantidade','Origem','Documento'],S.moves.filter(m=>S.locations.find(l=>l.id===m.loc)?.unit===S.unit).slice().reverse().slice(0,100).map(m=>`<tr><td>${dt(m.date)}</td><td>${esc(product(m.product).name)}<small>${esc(product(m.product).ref)}</small></td><td>${locName(m.loc)}</td><td class="${m.qty<0?'red':'green'}">${m.qty>0?'+':''}${num(m.qty)}</td><td>${esc(m.reason)}</td><td>${esc(m.ref||'—')}</td></tr>`)):`<form class="filters" data-form="catalog-search"><label class="search"><span>Buscar por produto, referência ou código de barras</span><input name="q" value="${esc(filter.catalogq||'')}" placeholder="Nome, referência ou código"></label><button class="btn" type="submit">${icon('search')}Buscar</button>${button('Limpar','clear-filter')}</form>${t==='etiquetas'?notice('Etiquetas por variante com código de barras interno (Code 39). Selecione um produto para imprimir.')+table(['Produto','Variante','Código','Preço',''],ps.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.color)} / ${esc(p.size)}</td><td>${esc(p.barcode)}</td><td>${brl(p.price)}</td><td>${button('Imprimir etiqueta','label',p.id,'sm','print')}</td></tr>`)):catalogCards(ps)}`)}
function orders(){const t=tab.pedidos||'todos',q=(filter.orderq||'').toLowerCase();let list=scoped(S.orders).filter(o=>(t==='todos'||(t==='orcamentos'?o.status==='Orçamento':t==='devolucoes'?S.returns.some(r=>r.orderId===o.id):o.status!=='Orçamento'))&&(!q||[o.client,o.id].join(' ').toLowerCase().includes(q)));return header('Orçamento e venda no mesmo fluxo, do atendimento ao faturamento.',button('Exportar CSV','export-orders','','','download')+button('Novo orçamento','budget','','primary','plus'))+tabs([['todos','Todos'],['orcamentos','Orçamentos'],['vendas','Faturados'],['devolucoes','Devoluções']],t)+`<form class="filters" data-form="order-search"><label class="search"><span>Cliente ou documento</span><input name="q" value="${esc(filter.orderq||'')}" placeholder="Buscar cliente ou número"></label><button class="btn">Buscar</button>${button('Limpar','clear-filter')}</form>`+list.map(o=>`<article class="card order-card"><div><h3>${o.id} · ${esc(o.client)}</h3><p class="small muted">${dt(o.date)} · ${unitName(o.unit)} · ${o.items.reduce((a,i)=>a+i.qty,0)} peça(s) · ${esc(o.method)}</p><div class="row mt">${badge(o.channel,'blue')}${badge(o.status,o.status==='Orçamento'?'amber':o.status==='Devolvido'?'red':'green')}${o.commission?badge('Comissão: '+brl(o.commission)):''}</div></div><div class="right"><div class="total">${brl(netOrder(o))}</div><div class="actions">${button('Detalhes','order',o.id,'sm')}${o.status==='Orçamento'?button('Faturar','invoice-budget',o.id,'sm primary'):o.status!=='Devolvido'?button('Devolver produto','return',o.id,'sm'):''}</div></div></article>`).join('')||empty()}
function cartBox(channel){const sub=cart.reduce((a,x)=>a+product(x.product).price*x.qty,0);return `<section class="card cart"><h2>Carrinho</h2>${cart.length?cart.map((x,i)=>`<div class="cart-line"><div class="space"><strong>${esc(product(x.product).name)}</strong><button class="icon-btn" data-action="cart-remove" data-id="${i}" aria-label="Remover ${esc(product(x.product).name)}">${icon('close')}</button></div><small class="muted">${esc(product(x.product).color)} / ${esc(product(x.product).size)}</small><div class="space mt"><input class="qty" type="number" min="1" step="1" value="${x.qty}" data-cart="${i}" aria-label="Quantidade de ${esc(product(x.product).name)}"><span>${brl(product(x.product).price*x.qty)}</span></div></div>`).join(''):empty('Nenhum item selecionado.')}<form data-form="checkout"><input type="hidden" name="channel" value="${channel}"><div class="stack mt">${input('Cliente','client','','text','placeholder="Nome do cliente"')}${select('Pagamento (simulado)','method',['Pix','Cartão','Dinheiro','Boleto'],'Pix')}${input('Desconto (R$)','discount','0','number','min="0" step="0.01" data-live="discount"')}<dl class="totals"><dt>Subtotal</dt><dd>${brl(sub)}</dd><dt class="total">Total</dt><dd class="total" id="cart-total">${brl(sub)}</dd></dl><button class="btn primary full" ${!cart.length?'disabled':''}>${channel==='Loja física'?'Finalizar venda':'Finalizar compra simulada'}</button></div><p class="form-error" role="alert"></p></form></section>`}
function pos(channel='Loja física'){const cash=scoped(S.cash).find(c=>c.open&&c.users.includes(S.user));const q=(filter.posq||'').toLowerCase(),ps=S.products.filter(p=>p.active&&p.kind==='acabado'&&(channel==='Loja física'||p.published)&&(!q||[p.name,p.ref,p.barcode].join(' ').toLowerCase().includes(q)));return header(channel==='Loja física'?`${unitName(S.unit)} · ${cash?cash.name+' aberto':'Nenhum caixa autorizado aberto'}`:channel==='E-commerce'?'Prévia da loja · integração externa prevista para uma etapa futura.':'Compra assistida com o estoque da unidade.',channel==='Loja física'?`<a class="btn" href="#caixa">Controle de caixa</a>`:'')+(channel!=='Loja física'?notice('Canal em demonstração. Nenhum pagamento ou pedido é enviado a plataformas externas.'):'')+`<div class="pos"><section><form class="filters" data-form="pos-search"><label class="search"><span>Produto, referência ou código de barras</span><input name="q" value="${esc(filter.posq||'')}" placeholder="Buscar produto ou ler código"></label><button class="btn">Buscar</button>${button('Limpar','clear-filter')}</form><div class="pos-products">${ps.map(p=>`<button class="pos-product" data-action="cart-add" data-id="${p.id}" ${F.at(S,p.id,S.unit)<=0?'disabled':''}><strong>${esc(p.name)}</strong><small>${esc(p.ref)} · ${esc(p.color)} / ${esc(p.size)}</small><div class="price">${brl(p.price)}</div><small>${num(F.at(S,p.id,S.unit))} peças nesta unidade</small></button>`).join('')||empty('Nenhum produto disponível.')}</div>${channel==='Autoatendimento'?`<div class="card mt"><h2>Acompanhar uma compra</h2><form class="filters" data-form="track">${input('Número da venda','id','','text','placeholder="VEN-..." required')}<button class="btn">Buscar</button></form>${button('Chamar vendedor','call-seller')}</div>`:''}</section>${cartBox(channel)}</div>`}
function cashPage(){return header('Unidade atual: '+unitName(S.unit),button('Cadastrar caixa','cash-new','','primary','plus'))+`<div class="product-grid">${scoped(S.cash).map(c=>{const v=scoped(S.orders).filter(o=>o.cashId===c.id&&o.cashSession===c.session&&o.status!=='Orçamento');return `<article class="card"><div class="space"><h3>${esc(c.name)}</h3>${badge(c.open?'aberto':'fechado',c.open?'green':'')}</div><p class="small muted mt">${unitName(c.unit)} · ${c.users.map(id=>S.users.find(u=>u.id===id)?.name).filter(Boolean).map(esc).join(', ')}</p><div class="cash-values"><div><span>Valor inicial</span><strong>${brl(c.opening)}</strong></div><div><span>Vendas da sessão</span><strong>${brl(v.reduce((a,o)=>a+netOrder(o),0))}</strong></div><div><span>Dinheiro esperado</span><strong>${brl(F.cashExpected(S,c.id))}</strong></div><div><span>Cartão / Pix / boleto</span><strong>${brl(v.filter(o=>o.method!=='Dinheiro').reduce((a,o)=>a+netOrder(o),0))}</strong></div></div>${c.counted!==null?`<p class="small mb">Última conferência: ${brl(c.counted)} · diferença ${brl(c.difference||0)}</p>`:''}<div class="row">${button(c.open?'Fechar caixa':'Abrir caixa',c.open?'cash-close':'cash-open',c.id,'sm primary')}${c.open?button('Movimentar','cash-move',c.id,'sm'):''}${button('Configurar','cash-edit',c.id,'sm')}${button('Histórico','cash-history',c.id,'sm plain')}</div></article>`}).join('')||empty()}</div>`}
function consignmentPage(){let list=scoped(S.consignments),t=tab.consignacoes||'aberto';return header('Romaneios por representante, retorno das peças e acerto de comissão.',button('Novo romaneio','consign-new','','primary','plus'))+`<div class="stats">${stat('Romaneios em aberto',list.filter(o=>o.status!=='Fechado').length)}${stat('Peças em posse',list.reduce((a,o)=>a+o.items.reduce((b,i)=>b+i.qty-i.sold-i.returned,0),0))}${stat('Prazo vencido',list.filter(o=>o.due<F.today&&o.status!=='Fechado').length,'','','amber')}${stat('Comissões apuradas',brl(list.reduce((a,o)=>a+o.history.reduce((b,h)=>b+h.commission,0),0)))}</div>`+tabs([['aberto','Em aberto'],['historico','Histórico']],t)+list.filter(o=>t==='historico'||o.status!=='Fechado').map(o=>`<article class="card order-card"><div><h3>${o.id} · ${esc(S.contacts.find(c=>c.id===o.rep)?.name)}</h3><p class="small muted">Origem ${locName(o.from)} · enviado ${dt(o.date)} · prazo ${dt(o.due)}</p><p class="small mt">${o.items.reduce((a,x)=>a+x.qty,0)} peças enviadas · ${o.items.reduce((a,x)=>a+x.qty-x.sold-x.returned,0)} em posse · comissão ${o.commission}%</p></div><div class="right">${badge(o.status,o.status==='Fechado'?'green':'amber')}<div class="total">${brl(o.history.reduce((a,h)=>a+h.net,0))}</div><div class="actions">${o.status!=='Fechado'?button('Registrar acerto','settle',o.id,'sm primary'):''}${button('Detalhes','consign-details',o.id,'sm')}</div></div></article>`).join('')}
