function validateBackup(d){F.assert(d?.version===4&&/^\d{4}-\d{2}-\d{2}$/.test(d.today)&&d.today<=F.today&&/^\d{4}-\d{2}-\d{2}$/.test(d.floor)&&d.floor<=d.today,'Use uma cópia compatível, com datas válidas e sem data-base futura.');const keys=['products','moves','users','units','locations','orders','ops','consignments','titles','notes','returns','remittances','cash','cashMoves','checks','punches','activity','contacts','numberVoids'];keys.forEach(k=>F.assert(Array.isArray(d[k]),'Cópia inválida: '+k));F.assert(d.users.some(u=>u.id===d.user&&u.active&&u.units?.includes(d.unit)),'Usuário da cópia inválido.');d.products.forEach(p=>{F.assert(typeof p.id==='string'&&Number.isFinite(p.price)&&Number.isFinite(p.cost)&&/^[0-9]{6,14}$/.test(p.barcode),'Produto inválido na cópia.');F.assert(Array.isArray(p.prices),'Histórico de preço inválido.')});d.moves.forEach(m=>F.assert(Number.isFinite(m.qty)&&d.products.some(p=>p.id===m.product)&&d.locations.some(l=>l.id===m.loc),'Movimentação inválida.'));d.checks.forEach(c=>F.assert(!c.photo||/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(c.photo),'Imagem de cheque inválida.'));F.assert(Number.isInteger(d.sequence)&&d.settings&&d.targets,'Estrutura da cópia inválida.')}
